#!/data/data/com.termux/files/usr/bin/sh
# Termux:Boot hook generated by GhostLock (glroot.sh --persist).
# Termux holds the CE fscrypt key, so only the Termux app can install this.
# The exploit itself still has to run as uid 2000; reach it over the phone's
# own adbd on 127.0.0.1:5555 and use --boot (no mpnl channel needed).
export PATH="${PREFIX:-/data/data/com.termux/files/usr}/bin:$PATH"
ADB="${PREFIX:-/data/data/com.termux/files/usr}/bin/adb"
PORT="${ANDROID_ADB_SERVER_PORT:-5038}"
export ANDROID_ADB_SERVER_PORT="$PORT"
LOG="${HOME:-/data/data/com.termux/files/home}/glroot-boot.log"

say() { echo "$(date) $*" >> "$LOG"; }
say "boot hook start"

i=0
while [ "$(getprop sys.boot_completed 2>/dev/null)" != "1" ] && [ "$i" -lt 300 ]; do
  sleep 2
  i=$((i+1))
done

[ -x "$ADB" ] || { say "adb missing - pkg install android-tools"; exit 1; }

i=0
while [ "$i" -lt 60 ]; do
  "$ADB" connect 127.0.0.1:5555 >> "$LOG" 2>&1
  if "$ADB" -s 127.0.0.1:5555 shell true >/dev/null 2>&1; then
    say "adb connected"
    break
  fi
  sleep 10
  i=$((i+1))
done

"$ADB" -s 127.0.0.1:5555 shell sh /data/local/tmp/glroot.sh --boot >> "$LOG" 2>&1
rc=$?
say "glroot --boot rc=$rc"
exit $rc
